create or replace function public.admin_list_activity_events(p_limit integer default 100) returns setof public.activity_events language sql security definer set search_path = public, auth, extensions, pg_catalog as $$ select e.* from public.activity_events e where public.is_platform_owner() order by e.created_at desc limit greatest(1, least(coalesce(p_limit,100),500)); $$; revoke execute on function public.admin_list_activity_events(integer) from anon; grant execute on function public.admin_list_activity_events(integer) to authenticated;
